83	/**
84	 * Playing a run.
85	 *
86	 * Every noun on screen comes from the pack's vocabulary, and every step comes
87	 * from its declared flow. Nothing here knows what kind of game it is hosting:
88	 * which is the same claim the format makes, held to to the last label.
89	 */
90	export function RunView({
91	  pack,
92	  store,
93	  bench,
94	  remote,
95	}: {
96	  pack: Pack;
97	  /** Where the log lives; the device unless a bench says otherwise. */
98	  store?: RunStore;
99	  /**
100	   * A test run: the pack is being tried, not played. Nothing is saved
101	   * or shared, so the people, race and export panels have nothing to
102	   * hold, and the screen says so with a way back to where the trial began.
103	   */
104	  bench?: { from: string; onLeave: () => void };
105	  /**
106	   * The remote alone, the next move, the last result, undo, as a page
107	   * of its own, for a streaming app's dock. The same controls the floating
108	   * window draws, on a page rather than in a window the browser floats;
109	   * it plays the run like any device, but announces nothing, since the
110	   * page it stands beside does that.
111	   */
112	  remote?: boolean;
113	}) {
114	  const run = useRun(pack, store);
115	  // The dock borrows the floating window's look, which is keyed on the document.
116	  useEffect(() => {
117	    if (!remote) return;
118	    document.documentElement.dataset["pip"] = "controls";
119	    return () => {
120	      delete document.documentElement.dataset["pip"];
121	    };
122	  }, [remote]);
123	
124	  // Sounds for what happens while nobody is looking at the screen. Hooked
125	  // here, before any early return, as hooks must be.
126	  const account = useAccount();
127	  const me = account.status === "signed-in" ? account.user.id : null;
128	  const [alerts, setAlerts] = useAlertSettings();
129	  const [settingsOpen, setSettingsOpen] = useState(false);
130	  const closeSettings = useCallback(() => setSettingsOpen(false), []);
131	  // The controls in a window of their own, for a streamer; see ControlPanel.
132	  // The window is asked for in the press, and closed with this screen.
133	  const [controlsWindow, setControlsWindow] = useState<Window | null>(null);
134	  const closeControls = useCallback(() => setControlsWindow(null), []);
135	  useEffect(() => () => controlsWindow?.close(), [controlsWindow]);
136	  const api = useApi();
137	  const [raceNote, setRaceNote] = useState<string | null>(null);
138	
139	  /**
140	   * A run shared by link keeps a snapshot on the server for anyone whose
141	   * device may not hold the pack: written from here after each move,
142	   * redacted here, where the pack and its license are.
143	   */
144	  const shared = Boolean(!remote && run.record && run.record.role !== "viewer" && (run.record.shared || liveLinkOf(run.record.runId)));
