import { useAlerts, useAlertSettings } from "../alerts/useAlerts.ts";
import { useAccount } from "../auth/Account.tsx";
import {
  clockOfUnit,
  compareScores,
  formatClock,
  formatScore,
  handsFree as handsFreeIn,
  nextUnit,
  scoreOf,
  unitPhases,
} from "@runlog/engine";
import type { Pack } from "@runlog/rules-schema";
import {
  closesUnit,
  constrainedByOf,
  constraintLines,
  constraintsFor,
  describeSkip,
