750	        on ? { t: "StateApplied", at, state: stateId, subject } : { t: "StateRemoved", at, state: stateId, subject },
751	      ]);
752	    },
753	    [commit, pack],
754	  );
755	
756	  /**
757	   * Move a tally by hand, when what was recorded was not what happened.
758	   *
759	   * Whose, where the pack keeps it per racer: the same correction on a
760	   * board of four is four different corrections, and the log should say
761	   * which of them it was.
762	   */
763	  const nudgeCounter = useCallback(
764	    (counter: string, by: number, contestant?: string) => {
765	      const at = now();
766	      const label = pack.counters?.[counter]?.label ?? counter;
767	      const who = contestant ? state?.contestants.find((c) => c.id === contestant)?.name : undefined;
768	      commit([
769	        { t: "Corrected", at, note: `${who ? `${who}: ` : ""}${label} ${by > 0 ? "+" : ""}${by}` },
770	        { t: "CounterChanged", at, counter, by, ...(contestant ? { contestant } : {}) },
771	      ]);
772	    },
773	    [commit, pack, state],
774	  );
775	
776	  /**
777	   * Turn a dial.
778	   *
779	   * Not a correction the way a nudged counter is. A counter is a tally
780	   * of what happened, so moving it by hand says the tally was wrong; a
781	   * resource is a setting, and turning it up mid-run is the run being
782	   * played, not repaired. So no `Corrected` marker above it.
783	   */
784	  const turnResource = useCallback(
785	    (resource: string, by: number) => {
786	      const def = pack.resources?.[resource];
787	      if (!def) return;
788	      const at = now();
789	      const current = state?.resources[resource] ?? def.initial;
790	      const next = Math.max(def.min ?? 0, Math.min(def.max ?? Infinity, current + by));
791	      if (next === current) return;
792	      commit([{ t: "ResourceChanged", at, resource, by: next - current }]);
793	    },
794	    [commit, pack, state],
795	  );
796	
797	  /** Counter thresholds that have come due and not yet fired. */
798	  const thresholds = useMemo(() => (state ? pendingTriggers(pack, state) : []), [pack, state]);
799	
800	  const fireThreshold = useCallback(
801	    (t: { counter: string; index: number; key: string; label: string }) =>
802	      begin({
803	        kind: "counterTrigger",
804	        trigger: { counter: t.counter, index: t.index, key: t.key },
805	        keyPrefix: t.key,
806	        label: t.label,
807	      }),
808	    [begin],
809	  );
810	
811	  /**
812	   * The pack's own triggers that have come due: what the game does of its own
813	   * accord rather than in answer to a roll. The end-of-run reckoning lives
814	   * here, which is why it outlives the run ending.
815	   */
816	  const globals = useMemo(() => (state ? pendingGlobalTriggers(pack, state) : []), [pack, state]);
817	
818	  const fireGlobal = useCallback(
819	    (g: { index: number; key: string; label: string }) =>
820	      begin({
821	        kind: "globalTrigger",
822	        global: { index: g.index, key: g.key },
823	        keyPrefix: g.key,
824	        label: g.label,
825	      }),
826	    [begin],
827	  );
828	
829	  /** Who holds which role this unit, for modes played by more than one person. */
830	  const roles = useMemo(() => rolesForUnit(pack, state), [pack, state]);
831	
832	  const resolveObligation = useCallback(
833	    (id: string, label: string) => begin({ kind: "obligation", obligationId: id, keyPrefix: `ob:${id}`, label }),
834	    [begin],
835	  );
836	
837	  /**
838	   * Undo the last player-visible move.
839	   *
840	   * Not by dropping its events: the log may be shared, and another player
841	   * may have built on it since. An `Undone` naming the move's events goes
842	   * on the end instead, and the reducer folds neither it nor them. From the
843	   * player's side it is the same undo; from the log's side nothing is lost.
844	   */
845	  const undo = useCallback(() => {
846	    setEvents((prev) => {
847	      const ids = undoableIds(prev, isBoundary);
848	      if (ids.length === 0) return prev;
849	      const next: RunEvent[] = [...prev, { t: "Undone", at: now(), id: ulid(), ids }];
850	      persist(next);
851	      return next;
852	    });
853	    setPending(null);
854	  }, [persist]);
855	
856	  /** Whether there is a move to undo: something after the start that still counts. */
857	  const canUndo = useMemo(() => undoableIds(events, isBoundary).length > 0, [events]);
858	
859	  /**
860	   * Draw again: the last draw unmade, with a note saying why, and the same
861	   * block run once more. Not in a seeded run, where a skipped draw would
862	   * put this device's dice out of step with everyone else's.
863	   */
864	  const canDrawAgain = useMemo(
865	    () => !seededRun && drawIsLast(events, lastDraw.current) && (pending === null || pending.kind !== "table"),
866	    [events, seededRun, pending],
867	  );
868	  const drawAgain = useCallback(
869	    (reason?: string) => {
870	      const draw = lastDraw.current;
871	      if (!draw || !canDrawAgain) return;
872	      lastDraw.current = null;
873	      commit(drawAgainEvents(draw, now(), reason));
874	      setPending(null);
875	      setRedraw(draw.block);
876	    },
877	    [canDrawAgain, commit],
878	  );
879	  // The block runs against the state the undo produced, which exists only
880	  // after the log has changed hands: hence a step later, not at once.
881	  useEffect(() => {
882	    if (!redraw || !state) return;
883	    setRedraw(null);
884	    begin(redraw);
885	  }, [redraw, state, begin]);
886	
887	  /** The open run's record, as storage has it: who is in it, and what this account may do. */
888	  const record = useMemo(() => runList.find((r) => r.runId === runId) ?? null, [runList, runId]);
889	
890	  /**
891	   * Write down what the server just said about taking asks.
892	   *
893	   * The record carries it, and the tray and the Chat panel both read it
894	   * there. Nothing in the log changes when a key is minted, so a sync pass
895	   * has no reason to fetch the session and no reason to notice: without
896	   * this the panel that made the key sits unchanged, and the key it showed
897	   * once is lost.
898	   */
899	  const setAsks = useCallback(
900	    async (asks: StoredRun["asks"]) => {
901	      const id = runIdRef.current;
902	      if (!id) return;
903	      const saved = await store.loadRun(id);
904	      if (!saved) return;
905	      await store.saveRun({ ...saved, asks });
906	      await refreshList();
907	    },
908	    [refreshList, store],
909	  );
910	  /**
911	   * Keep what a tool attached to the game should do about this run.
912	   *
913	   * The same shape of thing as the asks policy above, and kept the same
914	   * way: nothing about it is in the log, so no sync pass would ever
915	   * notice it had changed.
916	   */
917	  const setControl = useCallback(
918	    async (control: unknown) => {
919	      const id = runIdRef.current;
920	      if (!id) return;
921	      const saved = await store.loadRun(id);
922	      if (!saved) return;
923	      await store.saveRun({ ...saved, control });
924	      await refreshList();
925	    },
926	    [refreshList, store],
927	  );
928	  /**
929	   * Change the setup this run is played under, mid-run.
930	   *
931	   * The record and the ref both, because `persist` writes the ref over
932	   * the record on every save: setting one without the other would last
933	   * until the next move and then quietly go back.
934	   */
935	  const setSetup = useCallback(
936	    async (setup: StoredRun["setup"]) => {
937	      const id = runIdRef.current;
938	      if (!id) return;
939	      extrasRef.current = { ...extrasRef.current, setup };
940	      const saved = await store.loadRun(id);
941	      if (!saved) return;
942	      await store.saveRun({ ...saved, setup });
943	      await refreshList();
944	    },
945	    [refreshList, store],
946	  );
947	  /** A viewer watches. Every move is shown; none can be made. */
948	  const readOnly = record?.role === "viewer";
949	
950	  /**
951	   * A clock that waits for a phase starts when the flow gets there.
952	   *
953	   * Arrival happens more ways than one step finishing: a phase can be
954	   * skipped past, a run can be reloaded standing in it, a rewind can
955	   * bring it round again. So this watches where the flow is rather than
956	   * riding on any one of those, and `clockOnPhase` returns nothing once
957	   * the unit's clock exists, which makes it safe to ask on every pass.
958	   */
959	  useEffect(() => {
960	    if (readOnly || !state || state.status !== "active" || !activeStep) return;
961	    const start = clockOnPhase(pack, state, activeStep.phase.id, now(), events);
962	    if (!start) return;
963	    // Joined to the move that brought the flow here rather than made a
964	    // move of its own, so one undo takes back the arrival and the clock
965	    // together. On its own it was a step the player had to undo past,
966	    // and undoing it put them back where they already were.
967	    const arrived = effectiveEvents(events).at(-1)?.move;
968	    commit([arrived ? { ...start, move: arrived } : start]);
969	  }, [pack, state, activeStep, readOnly, commit, events]);
970	
971	  /**
972	   * A step half answered comes back with the run.
973	   *
974	   * Declared before the writer below on purpose: effects run in order, and
975	   * the stored step must be read before an empty `pending` clears it.
976	   */
977	  const restoredFor = useRef<string | null>(null);
978	  useEffect(() => {
979	    if (!hydrated || !state || !runId || pending || readOnly || !store.keeps || restoredFor.current === runId) return;
980	    restoredFor.current = runId;
981	    const stored = loadHalfStep(runId);
982	    if (!stored) return;
983	    const p = stored.eventCount === events.length ? toPending(pack, stored) : null;
984	    if (!p) {
985	      clearHalfStep(runId);
986	      return;
987	    }
988	    runPending(p, p.answers, p.generated);
989	  }, [hydrated, state, runId, pending, readOnly, events.length, pack, runPending, store.keeps]);
990	
991	  useEffect(() => {
992	    if (!hydrated || !runId || !store.keeps) return;
993	    if (pending) saveHalfStep(runId, events.length, pending);
994	    else clearHalfStep(runId);
995	  }, [hydrated, pending, runId, events.length, store.keeps]);
996	
997	  /** What the block in flight has resolved so far, ahead of the log. */
998	  const pendingOutcomes = useMemo(() => outcomesAhead(pack, events, pending?.partial), [pack, events, pending?.partial]);
999	
1000	  /**
1001	   * Replace the run with one read back from a saved archive.
1002	   *
1003	   * A whole-log replacement rather than a merge: the log is the run, so half
1004	   * of one and half of another would not be a run at all. The archive is a
1005	   * backup, not an identity: the run keeps the name it has here, or gets one
1006	   * if this pack had no run yet, whatever the archive's first event says.
1007	   */
1008	  const loadEvents = useCallback(
1009	    (next: RunEvent[]) => {
1010	      // Always a run of its own: an archive dropped into a shared log would
1011	      // be somebody else's history spliced into everyone's. Ids come with
1012	      // the archive where it had them; the rest are stamped as on load.
1013	      const id = ulid();
1014	      name(id);
1015	      setPending(null);
1016	      void stampIds(id, next).then((stamped) => {
1017	        setEvents(stamped);
1018	        persist(stamped);
1019	      });
1020	    },
1021	    [persist],
1022	  );
1023	
1024	  const discard = useCallback(() => {
1025	    // A tombstone rather than a delete, so a device that synced this run can
1026	    // be told it is gone. Storage purges it once that has happened.
1027	    if (runIdRef.current) {
1028	      forgetActive(pack.id, runIdRef.current);
1029	      void forgetRun(runIdRef.current).then(() => refreshList());
1030	    }
1031	    clearLegacyRun(pack.id);
1032	    name(null);
1033	    setEvents([]);
1034	    setPending(null);
1035	  }, [pack, refreshList, store]);
1036	
1037	  /**
1038	   * Open another run of this pack on this device. The one that was open
1039	   * stays where it is, in the list, for coming back to.
1040	   */
1041	  const switchRun = useCallback(
1042	    (id: string) => {
1043	      void loadRun(id).then((saved) => {
1044	        if (!saved || saved.deletedAt) return;
1045	        choosingRef.current = false;
1046	        name(saved.runId);
1047	        setActiveRunFor(pack.id, saved.runId);
1048	        setLastActive({ packId: pack.id, runId: saved.runId });
1049	        setEvents(saved.events as RunEvent[]);
1050	        setPending(null);
1051	      });
1052	    },
1053	    [pack.id, store],
1054	  );
1055	
1056	  /**
1057	   * Ask for a fresh run without touching the one that is open: setup shows,
1058	   * and the open run stays in the list until the new one starts.
1059	   */
1060	  const beginAnother = useCallback(() => {
1061	    choosingRef.current = true;
1062	    name(null);
1063	    setActiveRunFor(pack.id, NEW_RUN);
1064	    setEvents([]);
1065	    setPending(null);
1066	  }, [pack.id, store]);
1067	
1068	  /** Back out of "another": the newest run of the pack is open again. */
1069	  const cancelAnother = useCallback(() => {
1070	    choosingRef.current = false;
1071	    void currentRun(pack.id).then((saved) => {
1072	      if (!saved) return;
1073	      name(saved.runId);
1074	      setActiveRunFor(pack.id, saved.runId);
1075	      setEvents(saved.events as RunEvent[]);
1076	    });
1077	  }, [pack.id, store]);
1078	
1079	  /* ---------------------------------------------------------------- *
1080	   * Derived helpers for the view
1081	   * ---------------------------------------------------------------- */
1082	
1083	  /** Which deferred triggers are due right now, given where the player is. */
1084	  const due = useMemo(() => {
1085	    if (!state) return [];
1086	    const reached: string[] = ["immediately", "onEnterUnit"];
1087	    if (state.subjects.some((s) => s.unit === state.unit && s.type)) reached.push("onDeclareSubject");
