1092	    // obligation due immediately, even one queued afterward -- the bell
1093	    // already rang.
1094	    if (state.clocks.some((c) => c.unit === state.unit && c.status === "done" && c.expired)) {
1095	      reached.push("onTimerExpired");
1096	    }
1097	    return reached.flatMap((point) => dueObligations(state, point));
1098	  }, [state, activePhases]);
1099	
1100	  const notes = useMemo(() => (state ? state.obligations.filter((o) => !o.resolved && o.kind === "note") : []), [state]);
1101	
1102	  /** Finalizing is blocked while the unit still owes something. */
1103	  const blockingObligations = useMemo(() => {
1104	    if (!state) return [];
1105	    return [...due, ...dueObligations(state, "onFinalize")].filter((o) => !o.resolved);
1106	  }, [state, due]);
1107	
1108	  return {
1109	    // state
1110	    events,
1111	    state,
1112	    started,
1113	    hydrated,
1114	    runId,
1115	    pending,
1116	    pendingOutcomes,
1117	    activeStep,
1118	    activePhases,
1119	    due,
1120	    notes,
1121	    moves,
1122	    thresholds,
1123	    globals,
1124	    roles,
1125	    blockingObligations,
1126	    seed,
1127	    autoRoll,
1128	    seededRun,
1129	    canEnd: state ? canEndRun(state) : { ok: false, reason: "not started" },
1130	
1131	    // settings
1132	    setSeed,
1133	    setAutoRoll,
1134	
1135	    // commands
1136	    startRun,
1137	    enterUnit,
1138	    begin,
1139	    answer,
1140	    abandonPending,
1141	    completeStep,
1142	    declareSubject,
1143	    renameSubject,
1144	    startUnitClock,
1145	    pauseClock,
1146	    resumeClock,
1147	    stopClock,
1148	    moderated,
1149	    challenges: challengeList,
1150	    standings: standingsList,
1151	    award,
1152	    revokeAward,
1153	    reassignAward,
1154	    addContestant,
1155	    removeContestant,
1156	    markContestant,
1157	    check,
1158	    correctState,
1159	    nudgeCounter,
1160	    renameRun,
1161	    finalizeUnit,
1162	    closeAndEnter,
1163	    finish,
1164	    writeJournal,
1165	    resolveObligation,
1166	    takeMove,
1167	    turnResource,
1168	    fireThreshold,
1169	    fireGlobal,
1170	    endRun,
1171	    undo,
1172	    canUndo,
1173	    drawAgain,
1174	    canDrawAgain,
1175	    discard,
1176	    loadEvents,
1177	    runList,
1178	    record,
1179	    setAsks,
1180	    setControl,
1181	    setSetup,
1182	    readOnly,
1183	    switchRun,
1184	    beginAnother,
1185	    cancelAnother,
1186	  };
1187	}
1188	
1189	/**
1190	 * Which unit an event happened in.
1191	 *
1192	 * Events carry no unit stamp of their own, so it is counted from the
1193	 * `UnitEntered` markers ahead of them in the log.
1194	 */
1195	function unitOf(events: RunEvent[], event: RunEvent): number {
1196	  let seen = 0;
1197	  for (const e of events) {
1198	    if (e.t === "UnitEntered") seen += 1;
1199	    if (e === event) return seen;
1200	  }
1201	  return -1;
1202	}
1203	
1204	/** Events that begin a player-visible move, used as undo boundaries. */
1205	function isBoundary(e: RunEvent): boolean {
1206	  return (
1207	    e.t === "UnitEntered" ||
1208	    e.t === "StepCompleted" ||
1209	    e.t === "SubjectRenamed" ||
1210	    e.t === "Checked" ||
1211	    e.t === "Corrected" ||
1212	    e.t === "ClockStarted" ||
1213	    e.t === "ClockPaused" ||
1214	    e.t === "ClockResumed" ||
1215	    e.t === "ClockStopped" ||
1216	    e.t === "Awarded" ||
1217	    e.t === "ContestantAdded" ||
1218	    e.t === "ContestantRemoved" ||
1219	    e.t === "ContestantStateApplied" ||
1220	    e.t === "ContestantStateRemoved" ||
1221	    e.t === "Rolled" ||
1222	    e.t === "ObligationResolved" ||
1223	    e.t === "JournalWritten" ||
1224	    e.t === "RunEnded"
1225	  );
1226	}
