function ClosingStep({
  pack,
  run,
  state,
  active,
  ticked,
  tick,
}: {
  pack: Pack;
  run: ReturnType<typeof useRun>;
  state: RunState;
  active: ActiveStep;
  ticked: Set<string>;
  tick: (keys: string[], on: boolean, tally?: string) => void;
}) {
  const { phase, step, index } = active;
  const v = pack.vocabulary;
